/**
 * The Worker's environment.
 *
 * `Env` is generated by `bun run types` from wrangler.example.jsonc into
 * worker-configuration.d.ts. Some of it is optional and therefore typed here:
 *
 * - `HOST`, the service binding to tau-host (ADR 0013 §6), added by `bun run configure
 *   --host-service NAME`. Without it the universe cannot bind handles, forwards nothing and
 *   cannot relay visitors to hosted sub-taus.
 * - `UNIVERSE_IDENTITY`, the universe's own network identity (ADR 0013 §5), a secret in
 *   tau-net's `TAU_NET_IDENTITY` form (`bun run identity`). Without it the universe has no
 *   card and no inbox and cannot relay visitors to hub-run sub-taus.
 * - The Rate Limiting bindings `CHAT_IP_LIMIT`, `INBOX_IP_LIMIT` and `INBOX_SENDER_LIMIT`. A
 *   universe configured before they existed skips those checks and logs it once.
 */

export type LimiterName = "CHAT_IP_LIMIT" | "INBOX_IP_LIMIT" | "INBOX_SENDER_LIMIT";

export type UniverseEnv = Omit<Env, LimiterName> &
  Partial<Pick<Env, LimiterName>> & {
    HOST?: Fetcher;
    UNIVERSE_IDENTITY?: string;
  };

/** The one Directory instance every request talks to. */
export const DIRECTORY_NAME = "universe";

export function directoryOf(env: UniverseEnv) {
  return env.DIRECTORY.getByName(DIRECTORY_NAME);
}

/** The Relay instance of one visitor thread (ADR 0013 §5): one object per thread id. */
export function relayOf(env: UniverseEnv, thread: string) {
  return env.RELAY.getByName(thread);
}
